package br.com.sussmartcare.queue.domain; import static org.assertj.core.api.Assertions.assertThat; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; class QueueEntryReturnPolicyTest{@Test void lateReturnKeepsClinicalPriorityButResetsOperationalAge(){var q=new QueueEntry(UUID.randomUUID(),UUID.randomUUID(),"HIGH");Instant original=q.getEnteredAt();q.updatePresence(PresenceState.OUTSIDE_FACILITY);q.requestReturn(Duration.ofMinutes(1),Duration.ZERO);q.evaluateDeadline(Instant.now().plus(Duration.ofMinutes(2)));assertThat(q.getStatus()).isEqualTo(QueueEntryStatus.MISSED_CALL);q.returned();assertThat(q.getClinicalPriority()).isEqualTo("HIGH");assertThat(q.getStatus()).isEqualTo(QueueEntryStatus.WAITING);assertThat(q.getEnteredAt()).isAfterOrEqualTo(original);}}
